async function observeMacOSPickerPhase(phase: string): Promise<void> {
  const directory = Services.env.get("FLOORP_TEST_MAC_OS_PICKER_PHASES");
  if (!directory) throw Error("External picker observer directory is missing");
  await IOUtils.writeUTF8(
    PathUtils.join(directory, phase + ".request.json"),
    JSON.stringify({ phase, browserTime: Date.now() }),
  );
  const end = Date.now() + 6000;
  const ack = PathUtils.join(directory, phase + ".ack.json");
  while (!(await IOUtils.exists(ack))) {
    if (Date.now() >= end) throw Error("External picker snapshot deadline: " + phase);
    await new Promise((resolve) => setTimeout(resolve, 25));
  }
}

